parameters.message:
={{ 
'🔎 Me falta información para completar esta comida.\n\n' +
$json.alimentos
  .filter(a => a.cantidad == null || a.unidad == null)
  .map(a => {
    const faltantes = [];
    if (a.cantidad == null) faltantes.push('cantidad');
    if (a.unidad == null) faltantes.push('unidad');
    return a.nombre + ': indicame ' + faltantes.join(' y ');
  })
  .join('\n') +
'\n\nPodés responder en un solo mensaje.'
}}

parameters.text:
={{
'Información faltante que se le solicitó al usuario:\n' +
$('Normalizar entrada W1').item.json.alimentos
.filter(a => a.cantidad == null || a.unidad == null)
.map(a => {
  const faltantes = [];
  if (a.cantidad == null) faltantes.push('cantidad');
  if (a.unidad == null) faltantes.push('unidad');

  return a.nombre +
    ' | falta: ' + faltantes.join(' y ') +
    ' | cantidad actual: ' + (a.cantidad ?? 'null') +
    ' | unidad actual: ' + (a.unidad ?? 'null');
})
.join('\n') +
'\n\nRespuesta del usuario:\n' +
$json.data.text
}}

assignments.value:
={{
  $('Normalizar entrada W1').item.json.alimentos.map(original => {
    const salida = $json.output;

    const actualizados = Array.isArray(salida)
      ? salida
      : salida
        ? [salida]
        : [];

    const actualizado = actualizados.find(
      nuevo => nuevo.nombre === original.nombre
    );

    return {
      nombre: original.nombre,
      nombre_api: original.nombre_api,
      cantidad: actualizado?.cantidad ?? original.cantidad,
      unidad: actualizado?.unidad ?? original.unidad
    };
  })
}}

={{
(() => {
  // Obtiene todos los nutrientes del alimento seleccionado en USDA.
  const nutrientes =
    $('Buscar Alimento USDA').item.json.foods[$json.output.indice].foodNutrients ?? [];

  // Busca primero el nutriente estándar de energía de USDA (nutrientId 1008).
  const energiaPorId = nutrientes.find(
    n => Number(n.nutrientId) === 1008
  );

  // Si no lo encuentra por ID, busca cualquier nutriente
  // de energía expresado en KCAL.
  const energiaPorNombre = nutrientes.find(
    n =>
      String(n.nutrientName ?? '').toLowerCase().includes('energy') &&
      String(n.unitName ?? '').toUpperCase() === 'KCAL'
  );

  // Devuelve las calorías encontradas.
  // Si USDA realmente no trae energía, devuelve null.
  return energiaPorId?.value ?? energiaPorNombre?.value ?? null;
})()
}}

